1	package custody
2	
3	import (
4		"errors"
5		"testing"
6	)
7	
8	// 交接集合里两条已确认交接常用的最小合法对象文本。确认人、接收时间等
9	// 接收事实齐全，只是编号/人员/数量不同，便于注入“同一编号两条记录”。
10	const rawTR001Confirmed = `"id":"TR-001","sampleId":"S1","fromHolder":"张三","fromLocation":"A","toHolder":"李四","toLocation":"B","qty":10000,"handedOverAt":"2026-10-02T10:00:00Z","confirmed":true,"receivedAt":"2026-10-02T11:00:00Z","confirmedBy":"李四"`
11	
12	const rawTR002Confirmed = `"id":"TR-002","sampleId":"S1","fromHolder":"李四","fromLocation":"B","toHolder":"王五","toLocation":"C","qty":6750,"handedOverAt":"2026-10-03T10:00:00Z","confirmed":true,"receivedAt":"2026-10-03T11:00:00Z","confirmedBy":"王五"`
13	
14	// 一份可正常打开的样品：初始 10.000、当前由王五在 C 持有剩余 6.750，
15	// 保管历史说明里提到 TR-001 仅是文字。
16	const rawSampleS1TwoHandovers = `"S1": {"id":"S1","initial":10000,"remaining":6750,"holder":"王五","location":"C","children":[],"history":[
17		  {"kind":"register","time":"2026-10-02T09:00:00Z","holder":"张三","location":"A"},
18		  {"kind":"transfer-in","time":"2026-10-02T11:00:00Z","holder":"李四","location":"B","detail":"交接 TR-001 确认接收"},
19		  {"kind":"transfer-in","time":"2026-10-03T11:00:00Z","holder":"王五","location":"C","detail":"交接 TR-002 确认接收，上一条是 TR-001"}
20		]}`
21	
22	// escapedTR001 是写入文件后形如 "<bslash>u0054R-001" 的 JSON 键字面文本：
23	// 双引号 Go 字符串里的 \\u0054 落盘为反斜杠+u0054，JSON 解码后成为 T，
24	// 因而与直接写出的 "TR-001" 表示同一编号。
25	const escapedTR001 = `"` + "\\u0054" + `R-001"`
26	
27	// escapedTR001InText 是说明文字中的同类转义，仅用于确认值文本不参与判重。
28	const escapedTR001InText = "\\u0054" + `R-001`
29	
30	// TestOpenRejectsAdjacentDuplicateTransferID 覆盖任务描述的核心损坏：
31	// 交接集合里同一编号 TR-001 相邻出现两次、内容不同。JSON 解码进 map 时
32	// 后一条会静默覆盖前一条，必须在读取时就判为重复，使整份文件打开失败
33	// （nil Store、ErrInvalid），并写明重复编号与“同一编号出现多次”的原因。
34	func TestOpenRejectsAdjacentDuplicateTransferID(t *testing.T) {
35		second := `"id":"TR-001","sampleId":"S1","fromHolder":"张三","fromLocation":"A","toHolder":"赵六","toLocation":"D","qty":10000,"handedOverAt":"2026-10-04T10:00:00Z","confirmed":false`
36		path := writeRawLedger(t, `{
37	  "version": 1,
38	  "samples": {`+rawSampleS1TwoHandovers+`},
39	  "transfers": {
40	    "TR-001": {`+rawTR001Confirmed+`},
41	    "TR-001": {`+second+`}
42	  }
43	}`)
44		mustRejectOpen(t, path, "TR-001", "出现多次")
45	}
46	
47	// TestOpenRejectsDuplicateTransferIDSeparatedByOthers 重复的两条记录隔着
48	// 其他交接时同样必须拒绝，不能只比较相邻键。
49	func TestOpenRejectsDuplicateTransferIDSeparatedByOthers(t *testing.T) {
50		path := writeRawLedger(t, `{
51	  "version": 1,
52	  "samples": {`+rawSampleS1TwoHandovers+`},
53	  "transfers": {
54	    "TR-001": {`+rawTR001Confirmed+`},
55	    "TR-002": {`+rawTR002Confirmed+`},
56	    "TR-001": {`+rawTR001Confirmed+`}
57	  }
58	}`)
59		mustRejectOpen(t, path, "TR-001", "出现多次")
60	}
61	
62	// TestOpenRejectsIdenticalDuplicateTransfer 两条记录内容完全相同也必须
63	// 拒绝：不能按确认状态、关联样品或内容是否一致挑选其中一条。
64	func TestOpenRejectsIdenticalDuplicateTransfer(t *testing.T) {
65		path := writeRawLedger(t, `{
66	  "version": 1,
67	  "samples": {`+rawSampleS1TwoHandovers+`},
68	  "transfers": {
69	    "TR-001": {`+rawTR001Confirmed+`},
70	    "TR-001": {`+rawTR001Confirmed+`}
71	  }
72	}`)
73		mustRejectOpen(t, path, "TR-001", "出现多次")
74	}
75	
76	// TestOpenRejectsDuplicateTransferIDViaUnicodeEscape 编号按 JSON 解码后
77	// 实际表示的文字判断：把 TR-001 的首字符 T 写成合法 Unicode 转义
78	// （U+0054）仍是同一编号，必须判为重复；错误信息写出解码后的实际文字
79	// TR-001。反引号字符串里的 T 原样写入文件，由 JSON 解码解释。
80	func TestOpenRejectsDuplicateTransferIDViaUnicodeEscape(t *testing.T) {
81		path := writeRawLedger(t, `{
82	  "version": 1,
83	  "samples": {`+rawSampleS1TwoHandovers+`},
84	  "transfers": {
85	    "TR-001": {`+rawTR001Confirmed+`},
86	    `+escapedTR001+`: {`+rawTR001Confirmed+`}
87	  }
88	}`)
89		mustRejectOpen(t, path, "TR-001", "出现多次")
90	}
91	
92	// TestOpenRejectsDuplicateWhenSurvivingRecordWouldValidate 覆盖“静默覆盖”
93	// 最危险的形态：同一编号先写 null 再写一条能通过全部核对的记录。解码进
94	// map 后只留下那条合法记录，旧实现会照常打开；唯一性检查必须在解码阶段
95	// 拦住它。
96	func TestOpenRejectsDuplicateWhenSurvivingRecordWouldValidate(t *testing.T) {
97		path := writeRawLedger(t, `{
98	  "version": 1,
99	  "samples": {`+rawSampleS1TwoHandovers+`},
100	  "transfers": {
101	    "TR-001": null,
102	    "TR-001": {`+rawTR001Confirmed+`},
103	    "TR-002": {`+rawTR002Confirmed+`}
104	  }
105	}`)
106		mustRejectOpen(t, path, "TR-001", "出现多次")
107	}
108	
109	// TestOpenDuplicateTransferFailsWholeFile 文件里另有完全正常的样品和交接
110	// 时，也不能只加载正常部分：整份打开失败、返回 nil Store、原文件保持
111	// 原样（mustRejectOpen 已断言文件字节不变）。
112	func TestOpenDuplicateTransferFailsWholeFile(t *testing.T) {
113		path := writeRawLedger(t, `{
114	  "version": 1,
115	  "samples": {
116	    "OK": {"id":"OK","initial":100,"remaining":100,"holder":"h","location":"l","children":[],"history":[]},
117	    "S1": {"id":"S1","initial":10000,"remaining":6750,"holder":"王五","location":"C","children":[],"history":[]}
118	  },
119	  "transfers": {
120	    "TR-001": {`+rawTR001Confirmed+`},
121	    "TR-001": {`+rawTR001Confirmed+`}
122	  }
123	}`)
124		mustRejectOpen(t, path, "TR-001", "出现多次")
125	}
126	
127	// TestOpenDoesNotMentionTransferIDInTextAsDuplicate 编号文字只出现在保管
128	// 历史说明或交接记录字段值（含 Unicode 转义写法、含未知字段）中，而键
129	// 各自不同，不能误报为重复。同一样品的两次转手按现有规则正常恢复。
130	func TestOpenDoesNotMentionTransferIDInTextAsDuplicate(t *testing.T) {
131		path := writeRawLedger(t, `{
132	  "version": 1,
133	  "samples": {`+rawSampleS1TwoHandovers+`},
134	  "transfers": {
135	    "TR-001": {`+rawTR001Confirmed+`},
136	    "TR-002": {`+rawTR002Confirmed+`,"note":"参见 TR-001（转义写法 `+escapedTR001InText+`），仅为说明文字"}
137	  }
138	}`)
