// UnmarshalJSON 按现有格式解码一份本地样品数据，并对整份文件里的交接集合
// 额外保证交接编号唯一。JSON 允许在同一对象里重复写出同名键：transfers
// 内部重复编号会被标准库解码进 map 时静默覆盖，而文件顶层写出两个同名
// transfers 字段时，标准库更是只保留最后一个字段的整张 map——仅靠解码后的
// map 既发现不了跨字段重复，还会丢掉前一个字段保存的接收事实。
//
// 因此 transfers 字段交给 transfersDecoder 逐个字段解码（见其文档）：
//   - 每个 transfers 字段都在原始 JSON 上做一次键级扫描，编号按 JSON
//     解码后实际表示的文字比较（合法 Unicode 转义与直接写出同一文字视为
//     同一编号）；判重集合跨所有同名字段共享，所以同一编号无论是在一个
//     字段内出现两次，还是分处两个 transfers 字段、中间隔着其他顶层字段
//     或其他编号的交接，都按重复处理；
//   - 一旦重复，无论两条内容是否完全相同、是否指向同一样品、确认状态
//     如何，都返回包装了 ErrInvalid 的错误，写明重复的交接编号以及
//     “同一编号出现多次”的原因；
//   - 没有重复时，多个同名字段中的记录合并进同一张表，不同编号分别只
//     出现在不同字段中仍能按编号查询，不因字段重名而误判冲突。
//
// 扫描只统计 transfers 对象自身的键，值整体跳过，所以样品保管历史说明、
// 交接记录字段值或其他说明文字中提到某编号不会被当作重复键。
func (l *ledger) UnmarshalJSON(raw []byte) error {
	var decoded struct {
		Version   int                `json:"version"`
		Samples   map[string]*sampleRecord `json:"samples"`
		Transfers *transfersDecoder  `json:"transfers"`
	}
	if err := json.Unmarshal(raw, &decoded); err != nil {
		return err
	}
	l.Version = decoded.Version
	l.Samples = decoded.Samples
	if decoded.Transfers != nil {
		l.Transfers = decoded.Transfers.records
	}
	return nil
}

// transfersDecoder 逐字段接收文件顶层每一个 transfers 值。encoding/json
// 对实现了 Unmarshaler 的指针字段只分配一次、每个同名字段都在同一实例上
// 调用一次 UnmarshalJSON，因此 seen 与 records 可以跨所有同名 transfers
// 字段累积：唯一性检查覆盖整份文件的全部交接集合，不重复的记录则逐字段
// 合并，避免标准库“重复字段只保留最后一个值”丢失前一个集合的记录。
type transfersDecoder struct {
	records map[string]*transferRecord
	seen    map[string]struct{}
}

// UnmarshalJSON 处理单个 transfers 字段值：先用标准解码完成语法、类型与
// 记录字段校验（null 解码为空表，数组或标量按标准类型错误拒绝），再在
// 原始 JSON 上按键扫描做唯一性判断，最后把该字段的记录并入总表。
func (t *transfersDecoder) UnmarshalJSON(data []byte) error {
	var next map[string]*transferRecord
	if err := json.Unmarshal(data, &next); err != nil {
		return err
	}
	if t.seen == nil {
		t.seen = make(map[string]struct{})
	}
	dup, err := repeatedTransferKey(data, t.seen)
	if err != nil {
		return err
	}
	if dup != "" {
		return fmt.Errorf("%w: 交接编号 %q 在交接集合中出现多次，同一交接编号在整份本地数据中只能对应一条交接记录；重复编号无法确定应保留哪一条接收事实或待确认信息，无法恢复",
			ErrInvalid, dup)
	}
	if len(next) == 0 {
		return nil
	}
	if t.records == nil {
		t.records = make(map[string]*transferRecord, len(next))
	}
	for k, v := range next {
		t.records[k] = v
	}
