		tok, err := dec.Token()
		if err != nil {
			return "", err
		}
		key, _ := tok.(string)
		if key != field {
			if err := skipJSONValue(dec); err != nil {
				return "", err
			}
			continue
		}
		// 找到目标字段：先取其起始 token，判断是否为对象。顶层出现多个
		// 同名字段时逐一检查，避免被标准库“取最后一个”的语义绕过判重。
		start, err := dec.Token()
		if err != nil {
			return "", err
		}
		d, ok := start.(json.Delim)
		if !ok || d != '{' {
			// null、标量或数组都不是对象，且该值已随上面的 Token 消费完毕。
			continue
		}
		seen := make(map[string]struct{})
		for dec.More() {
			kt, err := dec.Token()
			if err != nil {
				return "", err
			}
			k := kt.(string)
			if err := skipJSONValue(dec); err != nil {
				return "", err
			}
			if _, exists := seen[k]; exists {
				return k, nil
			}
			seen[k] = struct{}{}
		}
		// 消费目标对象的结束 '}'。
		if _, err := dec.Token(); err != nil {
			return "", err
		}
	}
	// 消费顶层对象的结束 '}'。
	if _, err := dec.Token(); err != nil {
		return "", err
	}
	return "", nil
}

